drop table if exists chb_asset_mapping_ex;
CREATE TABLE chb_asset_mapping_ex (
  UUID varchar(36)  NOT NULL COMMENT 'UUID',
  SVR_ASSET_CODE varchar(200)  DEFAULT NULL COMMENT '监管报送资产代码',
  SADAS_ASSET_CODE varchar(200)  DEFAULT NULL COMMENT '策略专户资产代码',
  CREATE_USER varchar(20)  NOT NULL COMMENT '创建人',
  CREATE_DEPT varchar(32)  DEFAULT NULL COMMENT '创建部门',
  CREATE_TIME datetime NOT NULL COMMENT '创建时间',
  UPDATE_USER varchar(20)  NOT NULL COMMENT '更新人',
  UPDATE_TIME datetime NOT NULL COMMENT '更新时间',
  DATA_SOURCE_JGBS varchar(20)  DEFAULT NULL COMMENT '监管报送数据来源',
  PRIMARY KEY (UUID) USING BTREE
) ENGINE=InnoDB COMMENT='资产代码映射表';

